import{c as a,Q as i,j as e,m as t}from"./chunks/framework.8JjYC3xy.js";const k=JSON.parse('{"title":"第二章：安装 Claude Code","description":"在 Windows / Mac 上安装 Claude Code，含国内网络与镜像方案","frontmatter":{"title":"第二章：安装 Claude Code","description":"在 Windows / Mac 上安装 Claude Code，含国内网络与镜像方案","lastVerified":"2026-02-24","officialDoc":"https://code.claude.com/docs/zh-CN/setup"},"headers":[],"relativePath":"guide/1-getting-started/2-installation.md","filePath":"guide/1-getting-started/2-installation.md"}'),l={name:"guide/1-getting-started/2-installation.md"};function d(n,s,o,p,h,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="第二章-安装-claude-code" tabindex="-1">第二章：安装 Claude Code <a class="header-anchor" href="#第二章-安装-claude-code" aria-label="Permalink to &quot;第二章：安装 Claude Code&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你能在自己电脑上装好并跑通 <code>claude</code>。装不上也能按排错表自救。</p></div><h2 id="什么是终端" tabindex="-1">什么是终端 <a class="header-anchor" href="#什么是终端" aria-label="Permalink to &quot;什么是终端&quot;">​</a></h2><p><strong>终端</strong>（Terminal）就是用打字来操作电脑的窗口。本教程所有命令都在这里输入。</p><ul><li><strong>Windows</strong>：PowerShell（开始菜单搜索即可）或 Windows Terminal</li><li><strong>Mac</strong>：Terminal（<code>Command + Space</code> 搜 &quot;Terminal&quot;）</li></ul><p>看到类似 <code>PS C:\\Users\\you&gt;</code> 或 <code>you@MacBook ~ %</code> 的提示符，就是在终端里了，可以输命令。</p><div class="tip custom-block"><p class="custom-block-title">粘贴命令</p><p>Windows：右键粘贴或 <code>Ctrl + Shift + V</code>。Mac：<code>Command + V</code>。</p></div><h2 id="选一种装法" tabindex="-1">选一种装法 <a class="header-anchor" href="#选一种装法" aria-label="Permalink to &quot;选一种装法&quot;">​</a></h2><p>Claude Code 提供多种安装渠道。国内用户按下面顺序试，装上一种就够。</p><h3 id="方案-a-原生安装脚本-推荐-不需要-node-js" tabindex="-1">方案 A：原生安装脚本（推荐，不需要 Node.js） <a class="header-anchor" href="#方案-a-原生安装脚本-推荐-不需要-node-js" aria-label="Permalink to &quot;方案 A：原生安装脚本（推荐，不需要 Node.js）&quot;">​</a></h3><p>这是官方首推的方式，装的是独立二进制，<strong>后台自动更新</strong>，也不用先装 Node.js。</p><p><strong>Mac / Linux / WSL：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://claude.ai/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p><strong>Windows（PowerShell）：</strong></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">claude.ai</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p><strong>Windows（CMD）：</strong></p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">curl -fsSL https://claude.ai/install.cmd -o install.cmd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> install.cmd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> del</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> install.cmd</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">国内网络可能卡在这一步</p><p>安装脚本要从 Anthropic 的服务器下载二进制。如果你没有代理，这一步可能超时或 403。别硬试，直接用下面的方案 B。</p></div><h3 id="方案-b-npm-安装-国内最稳-走镜像" tabindex="-1">方案 B：npm 安装（国内最稳，走镜像） <a class="header-anchor" href="#方案-b-npm-安装-国内最稳-走镜像" aria-label="Permalink to &quot;方案 B：npm 安装（国内最稳，走镜像）&quot;">​</a></h3><p>npm 是 Node.js 的包管理器，它的国内镜像 <code>registry.npmmirror.com</code> 在国内可直连，所以这条路对国内用户最可靠。</p><p><strong>1. 先装 Node.js（需要 22 或更高版本）</strong></p><p>从 <a href="https://nodejs.org" target="_blank" rel="noreferrer">https://nodejs.org</a> 下载 LTS 安装包，一路下一步即可。装完验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 应显示 v22.x 或更高</span></span></code></pre></div><p><strong>2. 换国内镜像（只需做一次）</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmmirror.com</span></span></code></pre></div><p><strong>3. 安装 Claude Code</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">小提示</p><ul><li><strong>不要</strong>加 <code>sudo</code>，会导致后续自动更新失败和权限问题</li><li>如果提示权限不足，改用方案 A，或修复 npm 全局目录权限</li><li>以后升级：<code>npm install -g @anthropic-ai/claude-code@latest</code></li></ul></div><h3 id="方案-c-homebrew-mac-用户" tabindex="-1">方案 C：Homebrew（Mac 用户） <a class="header-anchor" href="#方案-c-homebrew-mac-用户" aria-label="Permalink to &quot;方案 C：Homebrew（Mac 用户）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span></code></pre></div><p>升级：<code>brew upgrade claude-code</code>。注意 Homebrew 装的<strong>不会自动更新</strong>。</p><h3 id="方案-d-winget-windows-用户" tabindex="-1">方案 D：WinGet（Windows 用户） <a class="header-anchor" href="#方案-d-winget-windows-用户" aria-label="Permalink to &quot;方案 D：WinGet（Windows 用户）&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install Anthropic.ClaudeCode</span></span></code></pre></div><p>升级：<code>winget upgrade Anthropic.ClaudeCode</code>。同样不会自动更新。</p><h2 id="验证装好了没有" tabindex="-1">验证装好了没有 <a class="header-anchor" href="#验证装好了没有" aria-label="Permalink to &quot;验证装好了没有&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>看到类似 <code>2.1.xxx (Claude Code)</code> 的版本号就成功了。</p><p>再跑一次体检：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>它会检查版本、自动更新、PATH 和配置，有问题会直接告诉你。</p><h2 id="装不上-对照排错" tabindex="-1">装不上？对照排错 <a class="header-anchor" href="#装不上-对照排错" aria-label="Permalink to &quot;装不上？对照排错&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>解决</th></tr></thead><tbody><tr><td><code>curl</code> 报 403 / 超时 / <code>syntax error near unexpected token &#39;&lt;&#39;</code></td><td>网络到不了 Anthropic，或拿到的是错误页面</td><td>改用方案 B 的 npm 镜像</td></tr><tr><td><code>command not found: claude</code></td><td>安装目录不在 PATH 里</td><td>重开一个新终端窗口；仍不行看 <code>claude doctor</code> 的提示</td></tr><tr><td><code>EACCES</code> / 权限错误</td><td>npm 全局目录不可写</td><td>不要用 <code>sudo</code>，改 npm 前缀：<code>npm config set prefix ~/.npm-global</code> 并把 <code>~/.npm-global/bin</code> 加进 PATH</td></tr><tr><td>PowerShell 里 <code>&amp;&amp;</code> 报错</td><td>你在 PowerShell 里用了 CMD 的语法</td><td>换用上面的 PowerShell 命令</td></tr><tr><td>CMD 里 <code>irm</code> 不识别</td><td>你在 CMD 里用了 PowerShell 的语法</td><td>换用 CMD 那条，或直接开 PowerShell</td></tr><tr><td>npm 装完找不到二进制</td><td>镜像缺平台包，或包管理器禁用了 optionalDependencies</td><td>临时切官方源：<code>npm install -g @anthropic-ai/claude-code --registry=https://registry.npmjs.org</code></td></tr><tr><td>安装成功但每次启动都提示更新失败</td><td>用了 <code>sudo</code> 安装</td><td>卸载后用普通权限重装</td></tr></tbody></table><h2 id="顺带装两个工具-强烈建议" tabindex="-1">顺带装两个工具（强烈建议） <a class="header-anchor" href="#顺带装两个工具-强烈建议" aria-label="Permalink to &quot;顺带装两个工具（强烈建议）&quot;">​</a></h2><p>这两个不是必须的，但会让后面顺畅很多：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 版本控制，Claude 的很多操作要用它</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 数据分析、脚本类任务常用</span></span></code></pre></div><p>没装的话：</p><ul><li><strong>Git</strong>：<a href="https://git-scm.com" target="_blank" rel="noreferrer">https://git-scm.com</a> （Windows 装完会自带 Git Bash，Claude Code 在 Windows 上会优先用它当 shell，体验更好）</li><li><strong>Python</strong>：<a href="https://python.org" target="_blank" rel="noreferrer">https://python.org</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>打开终端，输入 <code>claude --version</code>，记下你的版本号</li><li>运行 <code>claude doctor</code>，看有没有标红的项</li><li>输入 <code>git --version</code>，确认 Git 可用</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>装好了，但还不能用——需要给它配一个能调用的账号。</p><p><a href="/claude-code-guide/guide/1-getting-started/3-api-key-setup.html">👉 第三章：第三方 API 中转配置</a></p>`,52)])])}const g=a(l,[["render",d]]);export{k as __pageData,g as default};
